"""Publication figures for the quantization study, regenerated by one command.

Every plotted number comes from a committed artifact: the statistics tables in
``results/quant/`` (written by ``inmotion quantize stats``), the before/after
latency CSVs in ``results/perf/`` (written by ``results/perf/run_bench.sh``), the
device benchmark JSONs in ``results/quant/``, and a small ``data/`` directory
this pipeline materialises under the figure output so each figure reads rows it
can be traced back to. Nothing is typed in by hand.

Chart selection follows the academic-plotting skill's rule for data figures
(heatmap for a grid of values, line for a trend, grouped bar for categories,
scatter for correlation), and the palette is Okabe-Ito, matching
``docs/isac/paper/make_figures.py``. The hardware is labelled as it is: a classic
ESP32-D0WD-V3 with 520 KB SRAM and no PSRAM, whose weights must be flash-mapped,
and a Celeron J3455 router with no AVX/FMA. A figure that implied otherwise would
be wrong.

Determinism
-----------
matplotlib stamps ``/CreationDate`` into PDFs from the wall clock, so two runs
seconds apart differ byte-wise unless ``SOURCE_DATE_EPOCH`` is set. :func:`run`
sets it to a fixed value (only when the operator has not), which makes the PDFs
byte-identical across runs as well as the PNGs.
"""

from __future__ import annotations

import hashlib
import json
import os
import re
from collections.abc import Callable
from dataclasses import dataclass
from pathlib import Path

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
from matplotlib.colors import ListedColormap  # noqa: E402
from matplotlib.figure import Figure  # noqa: E402
from matplotlib.lines import Line2D  # noqa: E402
from matplotlib.patches import Patch  # noqa: E402

from inmotion.viz.quant_figures_config import RunConfig  # noqa: E402

# ── Palette (Okabe-Ito, colourblind-safe) ──────────────────────────────────
BLUE = "#0072B2"
SKY = "#56B4E9"
GREEN = "#009E73"
ORANGE = "#E69F00"
VERMILLION = "#D55E00"
PINK = "#CC79A7"

MODEL_COLORS: dict[str, str] = {
    "lejepa": BLUE,
    "t_jepa": ORANGE,
    "ts_jepa": GREEN,
    "cf_jepa": PINK,
    "sigreg": VERMILLION,
}
DEVICE_COLORS: dict[str, str] = {"host": SKY, "router": ORANGE, "esp32": GREEN}
FIT_STATES = ("resident", "flash-mapped", "does not fit")
FIT_COLORS = {"resident": GREEN, "flash-mapped": SKY, "does not fit": VERMILLION}

PRECISIONS = ("fp32", "bf16", "fp16", "int8", "q8", "q4", "q2")
BITS = {"fp32": 32, "bf16": 16, "fp16": 16, "int8": 8, "q8": 8, "q4": 4, "q2": 2}
MARKERS = {"fp32": "o", "bf16": "s", "fp16": "D", "int8": "^", "q8": "v", "q4": "P", "q2": "X"}
MASKED = "#D9D9D9"

#: Widths that match the paper's column, in inches.
FIG_FULL = (7.16, 2.9)
FIG_WIDE = (7.16, 3.6)
FIG_PAIR = (7.16, 3.0)

#: The precision the coverage, Pareto and latency details are read at, and why:
#: q4 is the deployed scheme, and the parameter fraction is precision-independent
#: while the byte fraction moves only slightly with bit width.
DEPLOY_PRECISION = "q4"

#: Hardware budgets. Datasheet numbers are facts about the part; the router and
#: host figures are extracted from their own artifacts or from this machine, and
#: every row is written to ``data/device_budgets.csv`` with its source.
ESP32_RESIDENT_BYTES = 300 * 1024
"""~300 KB usable SRAM: 520 KB total, no PSRAM, minus firmware/heap headroom."""
ESP32_FLASH_BYTES = 4 * 1024 * 1024


