# ── Inputs ────────────────────────────────────────────────────────────────
@dataclass
class Inputs:
    """Everything the figures read, all of it loaded from artifacts."""

    size: pd.DataFrame
    accuracy: pd.DataFrame
    coverage: pd.DataFrame
    latency: pd.DataFrame
    budgets: pd.DataFrame
    esp32_measured: set[tuple[str, str]]
    """(model, precision) pairs an ESP32 actually executed, from its JSON."""


def _read_csv(path: Path, *, missing: str) -> pd.DataFrame:
    """Read a committed CSV, or fail with the command that would create it.

    ``float_precision="round_trip"`` is deliberate: pandas' default parser
    mis-parses the ts_jepa/cf_jepa fp32 MCCs by one ULP, and a figure pipeline
    has no business quietly disagreeing with the baseline guard.
    """
    path = Path(path)
    if not path.exists():
        raise FileNotFoundError(f"missing {path}; run `{missing}`")
    return pd.read_csv(path, float_precision="round_trip")


def _esp32_documents(data_dir: Path) -> list[tuple[Path, dict]]:
    """The ESP32 benchmark JSONs, one per measured clock, duplicates collapsed.

    A byte-identical alias is dropped rather than plotted twice, and the survivor
    is chosen by what the artifact says: the copy carrying ``clock_mhz`` wins,
    with the filename only breaking ties between two clocked copies. Picking by
    filename order instead is what lost the 888.48 ms row's clock, because the
    clockless alias sorted first.
    """
    by_digest: dict[str, list[tuple[Path, dict]]] = {}
    for path in sorted(Path(data_dir).glob("esp32_*.json")):
        payload = json.loads(path.read_text())
        by_digest.setdefault(hashlib.md5(path.read_bytes()).hexdigest(), []).append(
            (path, payload)
        )

    documents: list[tuple[Path, dict]] = []
    for copies in by_digest.values():
        # Keyed by what the payload says first, so no filename ordering (and no
        # md5 ordering) can promote a clockless alias over a measured copy.
        kept = min(
            copies,
            key=lambda item: (
                item[1].get("clock_mhz") is None,
                hashlib.md5(str(item[0]).encode()).hexdigest(),
                item[0].name,
            ),
        )
        if len(copies) > 1:
            dropped = ", ".join(str(path) for path, _ in copies if path != kept[0])
            print(
                f"  {dropped} is byte-identical to {kept[0]}; keeping it as the "
                "copy that carries the measured clock"
            )
        documents.append(kept)
    return documents


def _clock_label(payload: dict) -> str:
    """The clock the device ran at, from the measurement itself.

    ``clock_mhz`` is written by ``run_on_device.py`` from the device's own boot
    log, so this label is the run's property. The filename is deliberately not
    consulted: a label that moved when a file was renamed was the defect this
    function used to have.
    """
    clock = payload.get("clock_mhz")
    if clock is None:
        raise ValueError(
            "measurement has no clock_mhz field; re-measure with "
            "firmware/tools/run_on_device.py so the artifact names its own clock"
        )
    return f"{int(clock)} MHz"


def _exported_blob(data_dir: Path) -> int | None:
    """The flash blob the ESP32 really held, from its own artifacts.

    Every device artifact states the same blob, so the answer cannot depend on
    which filename sorts first; a disagreement is an error, not a coin toss.
    """
    blobs: set[int] = set()
    for path in Path(data_dir).glob("esp32_*.json"):
        payload = json.loads(path.read_text())
        if "weight_blob_bytes" in payload:
            blobs.add(int(payload["weight_blob_bytes"]))
    if len(blobs) > 1:
        raise ValueError(f"ESP32 artifacts disagree on the flash blob size: {sorted(blobs)}")
    return blobs.pop() if blobs else None


def _read_device_json(path: Path, *, missing: str) -> dict:
    """Read a device artifact, or fail the way ``_read_csv`` does.

    The device artifacts are tracked, so this should never fire in a fresh
    clone; when it does, it names the file and the command that writes it
    instead of surfacing a bare ``No such file or directory``.
    """
    path = Path(path)
    if not path.exists():
        raise FileNotFoundError(f"missing {path}; run `{missing}`")
    return json.loads(path.read_text())


def device_budgets(data_dir: Path, perf_dir: Path) -> pd.DataFrame:
    """Per-device memory budgets, each with the artifact that states it."""
    router = _read_device_json(
        Path(data_dir) / "edge_router_j3455.json", missing="sh run_bench.sh router"
    )
    router_mb = int(router["device"]["ram_available_mb"])
    blob = _exported_blob(data_dir)

    host_mb = None
    try:
        for line in Path("/proc/meminfo").read_text().splitlines():
            if line.startswith("MemTotal:"):
                host_mb = round(int(line.split()[1]) / 1024)
    except OSError:
        host_mb = None
    if host_mb is None:
        raise RuntimeError("cannot read MemTotal from /proc/meminfo for the host budget")

    return pd.DataFrame(
        [
            {
                "device": "esp32",
                "device_label": "ESP32-D0WD-V3 (classic, no PSRAM)",
                "kind": "resident",
                "budget_bytes": ESP32_RESIDENT_BYTES,
                "source": (
                    "part spec 520 KB SRAM / no PSRAM; ~300 KB usable for weights "
                    f"(results/quant/esp32_*.json measure {blob} B flash-mapped, "
                    "heap free 193872 B)"
                ),
            },
            {
                "device": "esp32",
                "device_label": "ESP32-D0WD-V3 (classic, no PSRAM)",
                "kind": "flash",
                "budget_bytes": ESP32_FLASH_BYTES,
                "source": "part spec 4 MB flash; weights must be memory-mapped from it",
            },
            {
                "device": "router",
                "device_label": "wave-router (Celeron J3455, no AVX/FMA)",
                "kind": "resident",
                "budget_bytes": router_mb * 1_000_000,
                "source": f"results/quant/edge_router_j3455.json:ram_available_mb={router_mb}",
            },
            {
                "device": "host",
                "device_label": "this machine (i5-1135G7)",
                "kind": "resident",
                "budget_bytes": host_mb * 1024 * 1024,
                "source": "/proc/meminfo MemTotal at generation",
            },
        ]
    )


def load_latency(cfg: RunConfig) -> tuple[pd.DataFrame, set[tuple[str, str]]]:
    """Materialise the latency rows the figures read: one row per measurement.

    Host and router rows come from ``results/perf/summary.csv`` (before and after
    builds, so the acceleration is visible next to the absolute time); ESP32 rows
    come from the on-device JSONs, which carry a nested ``latency_ms`` block.
    """
    summary = _read_csv(
        Path(cfg.perf_dir) / "summary.csv", missing="sh run_bench.sh host|router"
    )
    rows: list[dict[str, object]] = []
    for record in summary.to_dict("records"):
        for build, median_key, p95_key in (
            ("before", "before_median_ms", "before_p95_ms"),
            ("after", "after_median_ms", "after_p95_ms"),
        ):
            median = float(record[median_key])
            rows.append(
                {
                    "device": record["device"],
                    "runtime": "rust static musl (transformer/CNN kernels)",
                    "model": record["model"],
                    "precision": record["precision"],
                    "build": build,
                    "median_ms": median,
                    "p95_ms": float(record[p95_key]),
                    "throughput_per_s": round(1000.0 / median, 1),
                    "artifact": "results/perf/summary.csv",
                }
            )

    measured: set[tuple[str, str]] = set()
    for path, payload in _esp32_documents(Path(cfg.data_dir)):
        latency = payload["latency_ms"]
        median = float(latency["median"])
        rows.append(
            {
                "device": "esp32",
                "runtime": f"esp32 no_std, flash-mapped ({_clock_label(payload)})",
                "model": payload["model"],
                "precision": payload["precision"],
                "build": "deployed",
                "median_ms": median,
                "p95_ms": float(latency["max"]),
                "throughput_per_s": round(1000.0 / median, 2),
                "artifact": f"results/quant/{path.name}",
            }
        )
        measured.add((payload["model"], payload["precision"]))
    return pd.DataFrame(rows), measured


def load_inputs(cfg: RunConfig) -> Inputs:
    data_dir = Path(cfg.data_dir)
    latency, measured = load_latency(cfg)
    return Inputs(
        size=_read_csv(data_dir / "stats_size.csv", missing="uv run inmotion quantize stats"),
        accuracy=_read_csv(
            data_dir / "stats_accuracy.csv", missing="uv run inmotion quantize stats"
        ),
        coverage=_read_csv(
            data_dir / "stats_coverage.csv", missing="uv run inmotion quantize stats"
        ),
        latency=latency,
        budgets=device_budgets(data_dir, Path(cfg.perf_dir)),
        esp32_measured=measured,
    )


def write_data_tables(inputs: Inputs, out_dir: Path) -> list[Path]:
    """Persist what the figures read, so every plotted value has a CSV row."""
    data_dir = Path(out_dir) / "data"
    data_dir.mkdir(parents=True, exist_ok=True)
    written = []
    for name, frame in (
        ("fig1_device_budgets.csv", inputs.budgets),
        ("fig5_latency_rows.csv", inputs.latency),
    ):
        path = data_dir / name
        frame.to_csv(path, index=False)
        written.append(path)
        print(f"wrote {path}  ({len(frame)} rows)")
    return written


# ── Figure 1: the fits/does-not-fit map (headline) ────────────────────────
def _fit_state(requirement: int, budgets: pd.DataFrame, device: str) -> str:
    rows = budgets[budgets.device == device]
    resident = int(rows[rows.kind == "resident"].budget_bytes.iloc[0])
    if requirement <= resident:
        return "resident"
    flash = rows[rows.kind == "flash"]
    if not flash.empty and requirement <= int(flash.budget_bytes.iloc[0]):
        return "flash-mapped"
    return "does not fit"


def fig_fits_map(inputs: Inputs) -> Figure:
    """Which (model, precision) artifacts fit which device, and in what memory.

    The workload is memory-bound, so this is the headline: the same artifact is
    resident on a laptop, resident on the router, and only flash-mappable - or
    impossible - on the ESP32.
    """
    devices = ["esp32", "router", "host"]
    labels = dict(zip(inputs.budgets.device, inputs.budgets.device_label, strict=True))
    models = list(MODEL_COLORS)
    requirement = (
        inputs.size.set_index(["model", "precision"]).total_mb.to_dict()
    )

    codes = {state: index for index, state in enumerate(FIT_STATES)}
    fig, axes = plt.subplots(1, len(devices), figsize=FIG_FULL, sharey=True)
    for ax, device in zip(axes, devices, strict=True):
        grid = np.full((len(models), len(PRECISIONS)), np.nan)
        for i, model in enumerate(models):
            for j, precision in enumerate(PRECISIONS):
                if (model, precision) not in requirement:
                    continue
                requirement_bytes = int(requirement[(model, precision)] * 1e6)
                state = _fit_state(requirement_bytes, inputs.budgets, device)
                grid[i, j] = codes[state]
        cmap = ListedColormap([FIT_COLORS[state] for state in FIT_STATES])
        ax.imshow(grid, cmap=cmap, vmin=-0.5, vmax=len(FIT_STATES) - 0.5, aspect="auto")
        for i, model in enumerate(models):
            for j, precision in enumerate(PRECISIONS):
                if (model, precision) not in requirement:
                    continue
                mb = requirement[(model, precision)]
                text = f"{mb:.2f}" if mb < 1 else f"{mb:.1f}"
                ax.text(j, i, text, ha="center", va="center", fontsize=5.0, color="#111111")
                if device == "esp32" and (model, precision) in inputs.esp32_measured:
                    ax.text(
                        j + 0.34,
                        i - 0.30,
                        "*",
                        ha="center",
                        va="center",
                        fontsize=6.5,
                        color="#111111",
                    )
        budget = inputs.budgets[(inputs.budgets.device == device)]
        resident = int(budget[budget.kind == "resident"].budget_bytes.iloc[0]) / 1e6
        ax.set_title(f"{labels[device]}\nbudget {resident:,.1f} MB resident", fontsize=6.6)
        ax.set_xticks(range(len(PRECISIONS)), PRECISIONS, rotation=60)
        ax.set_yticks(range(len(models)), models)
        ax.set_xticks(np.arange(-0.5, len(PRECISIONS), 1), minor=True)
        ax.set_yticks(np.arange(-0.5, len(models), 1), minor=True)
        ax.grid(which="minor", color="white", linewidth=1.0)
        ax.grid(which="major", visible=False)
        ax.tick_params(which="minor", length=0)

    handles = [Patch(facecolor=FIT_COLORS[state], label=state) for state in FIT_STATES]
    handles.append(Patch(facecolor="none", edgecolor="none", label="cell = artifact MB"))
    handles.append(Patch(facecolor="none", edgecolor="none", label="* = executed on the device"))
    fig.legend(
        handles=handles,
        loc="lower center",
        ncol=5,
        bbox_to_anchor=(0.5, -0.06),
        handlelength=1.2,
    )
    fig.suptitle(
        "Where each quantized world model fits: memory budget per device "
        "(weights must be flash-mapped on the ESP32)",
        fontsize=8.5,
        y=1.06,
    )
    fig.tight_layout()
    return fig


# ── Figure 2: size-accuracy Pareto frontier ───────────────────────────────
def _pareto(frame: pd.DataFrame, value: str) -> pd.DataFrame:
    """Non-dominated points: smallest size for each accuracy level reached."""
    ordered = frame.sort_values("total_mb")
    best = -np.inf
    keep = []
    for _, row in ordered.iterrows():
        if row[value] > best:
            keep.append(row)
            best = row[value]
    return pd.DataFrame(keep)


def fig_pareto(inputs: Inputs) -> Figure:
    """Accuracy against artifact size, with each model's frontier marked."""
    merged = inputs.accuracy.merge(
        inputs.size[["model", "precision", "total_mb"]], on=["model", "precision"]
    )
    fig, ax = plt.subplots(figsize=FIG_WIDE)
    for model, group in merged.groupby("model", sort=False):
        colour = MODEL_COLORS[str(model)]
        ax.scatter(
            group.total_mb,
            group.mcc,
            s=16,
            facecolor="white",
            edgecolor=colour,
            linewidth=0.8,
        )
        frontier = _pareto(group, "mcc")
        ax.plot(
            frontier.total_mb,
            frontier.mcc,
            color=colour,
            marker="o",
            markersize=3.4,
            label=model,
        )
        for _, row in pd.concat([frontier.head(1), frontier.tail(1)]).iterrows():
            ax.annotate(
                row.precision,
                (row.total_mb, row.mcc),
                textcoords="offset points",
                xytext=(3, 3),
                fontsize=5.2,
                color=colour,
            )
    ax.set_xscale("log")
    ax.set_xlabel("artifact size on device (MB, log scale)")
    ax.set_ylabel("test MCC on dataset.csv")
    ax.set_title(
        "Size-accuracy Pareto frontier: the q2 collapse is the price of the smallest artifacts"
    )
    ax.legend(loc="lower right", ncol=2)
    fig.tight_layout()
    return fig


# ── Figure 3: accuracy against bit width ──────────────────────────────────
def fig_accuracy_bits(inputs: Inputs) -> Figure:
    """One line per model, so the cliff at low bit width is comparable."""
    fig, ax = plt.subplots(figsize=FIG_WIDE)
    accuracy = inputs.accuracy.copy()
    accuracy["bits"] = accuracy.precision.map(BITS)
    for model, group in accuracy.groupby("model", sort=False):
        group = group.sort_values("bits")
        colour = MODEL_COLORS[str(model)]
        ax.plot(group.bits, group.mcc, color=colour, alpha=0.45, zorder=1)
        for _, row in group.iterrows():
            ax.plot(
                row.bits,
                row.mcc,
                marker=MARKERS[row.precision],
                color=colour,
                markersize=4.2,
                markeredgecolor="white",
                markeredgewidth=0.4,
                linestyle="none",
                zorder=2,
            )
    ax.axhline(0.0, color="#666666", linewidth=0.7, linestyle=":")
    ax.text(2.2, 0.012, "MCC chance level", fontsize=5.6, color="#666666")
    ax.set_xticks([2, 4, 8, 16, 32])
    ax.set_xlabel("storage bit width (bf16 and fp16 coincide at 16)")
    ax.set_ylabel("test MCC on dataset.csv")
    ax.set_title("Accuracy against bit width on dataset.csv")
    handles: list[Line2D] = [
        Line2D([], [], color=MODEL_COLORS[m], marker="o", markersize=3.4, label=m)
        for m in MODEL_COLORS
    ]
    handles += [
        Line2D(
            [],
            [],
            color="#555555",
            marker=MARKERS[p],
            linestyle="none",
            markersize=3.6,
            label=p,
        )
        for p in PRECISIONS
    ]
    ax.legend(handles=handles, ncol=4, loc="lower right", fontsize=6.0)
    fig.tight_layout()
    return fig


# ── Figure 4: coverage ────────────────────────────────────────────────────
def fig_coverage(inputs: Inputs) -> Figure:
    """What quantization actually covered, and what it had to leave alone."""
    summary = inputs.coverage[
        (inputs.coverage.scope == "summary")
        & (inputs.coverage.precision == DEPLOY_PRECISION)
        & (inputs.coverage.scheme_kind == "affine")
    ].copy()
    summary["params_skipped_pct"] = (1 - summary.frac_params_quantized) * 100
    summary["bytes_skipped_pct"] = (1 - summary.frac_bytes_quantized) * 100
    summary = summary.sort_values("frac_bytes_quantized")

    skipped = inputs.coverage[
        (inputs.coverage.scope == "tensor") & (inputs.coverage.precision == DEPLOY_PRECISION)
    ].copy()
    by_class = (skipped.groupby("tensor_class")["n_values"].sum() * 4 / 1e6).sort_values(
        ascending=True
    )

    fig, axes = plt.subplots(1, 2, figsize=FIG_PAIR, gridspec_kw={"width_ratios": [1.0, 1.35]})
    ax = axes[0]
    positions = np.arange(len(summary))
    width = 0.38
    ax.bar(
        positions - width / 2,
        summary.params_skipped_pct,
        width,
        color=BLUE,
        label="parameters skipped",
    )
    ax.bar(
        positions + width / 2,
        summary.bytes_skipped_pct,
        width,
        color=ORANGE,
        label="bytes not stored as codes",
    )
    for x, value in zip(positions, summary.bytes_skipped_pct, strict=True):
        ax.text(x + width / 2, value + 0.1, f"{value:.1f}", ha="center", fontsize=5.4)
    ax.set_xticks(positions, summary.model, rotation=30, ha="right")
    ax.set_ylabel(f"% left unquantized at {DEPLOY_PRECISION}")
    ax.set_title("Coverage of affine quantization")
    ax.legend(loc="upper left")
    ax.set_ylim(0, max(summary.bytes_skipped_pct.max(), 1) * 1.35)

    ax = axes[1]
    totals = [float(value) for value in by_class.to_numpy()]
    ax.barh(by_class.index, totals, color=SKY)
    for y, value in enumerate(totals):
        ax.text(value + 0.004, y, f"{value:.3f}", va="center", fontsize=5.2)
    ax.set_xlabel(f"skipped weight bytes over all five models at {DEPLOY_PRECISION} (MB)")
    ax.set_title("Skipped tensor classes")
    ax.tick_params(axis="y", labelsize=5.6)
    fig.tight_layout()
    return fig


# ── Figure 5: latency per device ──────────────────────────────────────────
def _runtime_clock(runtime: str, artifact: str) -> str:
    """The clock a latency row ran at, for the panel's y label.

    The clock is already in ``runtime`` for a row loaded from a clocked
    artifact; the filename is only consulted when that string predates the
    field, and then only so two legacy bars do not share a label.
    """
    clock = re.search(r"\((\d+ MHz)\)", runtime)
    if clock:
        return clock.group(1)
    # Fallback for a legacy runtime string, so a bar is still distinguishable.
    legacy = re.fullmatch(r".*?_(\d+)mhz\.json", artifact)
    return f"{legacy.group(1)} MHz" if legacy else "unknown clock"


def fig_latency(inputs: Inputs) -> Figure:
    """Median latency per device on a log scale: router beside this machine."""
    latency = inputs.latency
    fig, axes = plt.subplots(1, 2, figsize=FIG_WIDE, gridspec_kw={"width_ratios": [2.1, 1.0]})

    ax = axes[0]
    after = latency[latency.build == "after"]
    before = latency[latency.build == "before"]
    cells: list[tuple[str, str]] = list(
        dict.fromkeys(
            (str(model), str(precision))
            for model, precision in zip(after.model, after.precision, strict=True)
        )
    )
    ypos: dict[tuple[str, str], int] = {cell: index for index, cell in enumerate(cells)}
    height = 0.36
    for offset, frame, alpha in (
        (-height / 2, before, 0.35),
        (height / 2, after, 1.0),
    ):
        for device in ("host", "router"):
            subset = frame[frame.device == device]
            for record in subset.to_dict("records"):
                y = ypos[(record["model"], record["precision"])] + offset
                ax.barh(
                    y,
                    record["median_ms"],
                    height=height / 2,
                    color=DEVICE_COLORS[device],
                    alpha=alpha,
                    edgecolor="white",
                    linewidth=0.3,
                )
    for record in after.to_dict("records"):
        cell = (record["model"], record["precision"])
        before_row = before[
            (before.model == cell[0])
            & (before.precision == cell[1])
            & (before.device == record["device"])
        ]
        if before_row.empty:
            continue
        speedup = float(before_row.median_ms.iloc[0]) / record["median_ms"]
        ax.text(
            record["median_ms"] * 1.08,
            ypos[cell] + height / 2,
            f"x{speedup:.1f}",
            va="center",
            fontsize=5.0,
            color="#333333",
        )
    ax.set_yticks(range(len(cells)), [f"{m} {p}" for m, p in cells])
    ax.set_xscale("log")
    ax.set_xlim(min(latency.median_ms.min(), 0.5) * 0.8, latency.median_ms.max() * 6)
    ax.set_xlabel("median latency per inference (ms, log scale)")
    ax.set_title(
        "Rust kernels, before (pale) and after (solid): 300/200 iterations, best of 3 runs"
    )
    ax.legend(
        handles=[
            Patch(facecolor=DEVICE_COLORS["host"], label="this machine (i5-1135G7)"),
            Patch(facecolor=DEVICE_COLORS["router"], label="wave-router (Celeron J3455)"),
            Patch(facecolor="#888888", alpha=0.35, label="before (pre-optimisation kernel)"),
            Patch(facecolor="#888888", alpha=1.0, label="after"),
        ],
        loc="lower right",
        ncol=2,
    )
    ax.invert_yaxis()

    ax = axes[1]
    edge = latency[(latency.model == "lejepa") & (latency.precision == "int8")]
    edge = edge.sort_values("median_ms", ascending=False)
    # One y label per row: the same part measured at two clocks must not plot as
    # two bars with one label.
    labels = [
        f"ESP32-D0WD-V3\nflash-mapped ({_runtime_clock(str(row.runtime), str(row.artifact))})"
        if row.device == "esp32"
        else {"router": "wave-router", "host": "this machine"}[str(row.device)]
        for row in edge.itertuples()
    ]
    colors = [DEVICE_COLORS[str(row.device)] for row in edge.itertuples()]
    ax.barh(
        [f"{label}\n{build}" for label, build in zip(labels, edge.build, strict=True)],
        edge.median_ms,
        color=colors,
    )
    for y, value in enumerate(edge.median_ms):
        ax.text(value * 1.15, y, f"{value:,.2f} ms", va="center", fontsize=5.4)
    ax.set_xscale("log")
    ax.set_xlim(0.4, edge.median_ms.max() * 8)
    ax.set_xlabel("median latency, lejepa int8 (ms, log scale)")
    ax.set_title("The edge part is ~2 orders\nslower than the router")
    ax.tick_params(axis="y", labelsize=5.6)
    fig.tight_layout()
    return fig


# ── Figure 6: size and compression against bit width ──────────────────────
def fig_size_bits(inputs: Inputs) -> Figure:
    """Both memory questions: how many MB, and how much smaller than fp32."""
    size = inputs.size.copy()
    size["bits"] = size.precision.map(BITS)
    fig, axes = plt.subplots(1, 2, figsize=FIG_PAIR)
    for ax, column, label, logy in (
        (axes[0], "total_mb", "device bytes (MB, log scale)", True),
        (axes[1], "compression", "compression vs fp32 weights (x)", False),
    ):
        for model, group in size.groupby("model", sort=False):
            group = group.sort_values("bits")
            ax.plot(
                group.bits,
                group[column],
                color=MODEL_COLORS[str(model)],
                marker="o",
                markersize=3.0,
                label=model,
            )
        if logy:
            ax.set_yscale("log")
        ax.set_xticks([2, 4, 8, 16, 32])
        ax.set_xlabel("storage bit width")
        ax.set_ylabel(label)
    axes[0].set_title("Size per device artifact")
    axes[1].set_title("Compression of the quantized weights")
    axes[1].axhline(1.0, color="#666666", linewidth=0.7, linestyle=":")
    axes[1].legend(loc="upper right", ncol=1, fontsize=6.0)
    fig.tight_layout()
    return fig


# ── Pipeline ──────────────────────────────────────────────────────────────
FIGURES: tuple[tuple[str, Callable[[Inputs], Figure]], ...] = (
    ("fig1_fits_map", fig_fits_map),
    ("fig2_size_accuracy_pareto", fig_pareto),
    ("fig3_accuracy_vs_bits", fig_accuracy_bits),
    ("fig4_coverage", fig_coverage),
    ("fig5_latency_by_device", fig_latency),
    ("fig6_size_compression_vs_bits", fig_size_bits),
)


def run(cfg: RunConfig) -> int:
    """Render every figure from the committed CSVs. Returns a process exit code."""
    # Fixed timestamp: matplotlib stamps PDF CreationDate from the clock, which
    # would make two runs differ byte-wise for no informational gain.
    os.environ.setdefault("SOURCE_DATE_EPOCH", "1577836800")
    _style()

    out_dir = Path(cfg.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    inputs = load_inputs(cfg)
    write_data_tables(inputs, out_dir)

    for name, builder in FIGURES:
        figure = builder(inputs)
        for fmt in cfg.formats:
            path = out_dir / f"{name}.{fmt}"
            figure.savefig(path, dpi=cfg.dpi, bbox_inches="tight", facecolor="white")
            print(f"wrote {path}")
        plt.close(figure)
    print(f"\n{len(FIGURES)} figures x {len(cfg.formats)} formats in {out_dir}")
    return 0
